240	func cmdCatalogObservations(_ string, args []string) int {
241		fs := flag.NewFlagSet("catalog observations", flag.ContinueOnError)
242		fs.SetOutput(os.Stderr)
243		formatFlag := fs.String("format", "", "Output format: json")
244		providerFlag := fs.String("provider", "", "Filter by provider")
245		modelFlag := fs.String("model", "", "Filter by model")
246		if err := fs.Parse(args); err != nil {
247			return 2
248		}
249	
250		storePath := observations.DefaultStorePath()
251		store, err := observations.LoadStore(storePath)
252		if err != nil {
253			fmt.Fprintf(os.Stderr, "error: load observations: %v\n", err)
254			return 1
255		}
256	
257		// Collect and filter rows.
258		var rows []observationRow
259		for _, key := range store.AllKeys() {
260			if *providerFlag != "" && key.ProviderSystem != *providerFlag {
261				continue
262			}
263			if *modelFlag != "" && key.Model != *modelFlag {
264				continue
265			}
266			ring := store.RingFor(key)
267			if ring == nil || len(ring.Samples) == 0 {
268				continue
269			}
270			mean, ok := ring.Mean()
271			if !ok {
272				// All-zero samples — omit.
273				continue
274			}
275			rows = append(rows, observationRow{
276				ProviderSystem:        key.ProviderSystem,
277				Model:                 key.Model,
278				Samples:               len(ring.Samples),
279				AvgOutputTokensPerSec: mean,
280			})
281		}
282	
283		// Sort by provider then model for deterministic output.
284		sort.Slice(rows, func(i, j int) bool {
285			if rows[i].ProviderSystem != rows[j].ProviderSystem {
286				return rows[i].ProviderSystem < rows[j].ProviderSystem
287			}
288			return rows[i].Model < rows[j].Model
289		})
290	
291		if *formatFlag == "json" {
292			data, err := json.MarshalIndent(rows, "", "  ")
293			if err != nil {
294				fmt.Fprintf(os.Stderr, "error: marshal json: %v\n", err)
295				return 1
296			}
297			fmt.Println(string(data))
298			return 0
299		}
300	
301		// Human-readable table.
302		if len(rows) == 0 {
303			fmt.Println("no observations recorded yet")
304			return 0
305		}
306		fmt.Printf("%-16s %-28s %-8s %s\n", "PROVIDER", "MODEL", "SAMPLES", "AVG_TOK/S")
307		for _, r := range rows {
308			fmt.Printf("%-16s %-28s %-8d %.1f\n",
309				r.ProviderSystem, r.Model, r.Samples, r.AvgOutputTokensPerSec)
310		}
311		return 0
312	}
