351	func cmdCatalogUpdate(workDir string, args []string) int {
352		fs := flag.NewFlagSet("catalog update", flag.ContinueOnError)
353		fs.SetOutput(os.Stderr)
354		baseURL := fs.String("base-url", defaultCatalogBaseURL, "Published catalog base URL")
355		channel := fs.String("channel", "stable", "Channel to install")
356		version := fs.String("version", "", "Exact catalog version to install")
357		if err := fs.Parse(args); err != nil {
358			return 2
359		}
360	
361		cfg, _, manifestPath, err := loadCatalogRuntime(workDir)
362		if err != nil {
363			fmt.Fprintf(os.Stderr, "error: %s\n", err)
364			return 1
365		}
366		if cfg == nil {
367			cfg = &agentConfig.Config{}
368		}
369	
370		index, indexURL, err := fetchCatalogIndex(*baseURL, *channel, *version)
371		if err != nil {
372			fmt.Fprintf(os.Stderr, "error: %s\n", err)
373			return 1
374		}
375		manifestURL, err := resolveRelativeURL(indexURL, index.ManifestPath)
376		if err != nil {
377			fmt.Fprintf(os.Stderr, "error: %s\n", err)
378			return 1
379		}
380		manifestData, err := fetchURL(manifestURL)
381		if err != nil {
382			fmt.Fprintf(os.Stderr, "error: %s\n", err)
383			return 1
384		}
385		sum := sha256.Sum256(manifestData)
386		if got := hex.EncodeToString(sum[:]); !strings.EqualFold(got, index.ManifestSHA256) {
387			fmt.Fprintf(os.Stderr, "error: checksum mismatch: expected %s got %s\n", index.ManifestSHA256, got)
388			return 1
389		}
390	
391		if err := safefs.MkdirAll(filepath.Dir(manifestPath), 0o750); err != nil {
392			fmt.Fprintf(os.Stderr, "error: create manifest directory: %v\n", err)
393			return 1
394		}
395	
396		tmpFile, err := os.CreateTemp(filepath.Dir(manifestPath), "models-*.yaml")
397		if err != nil {
398			fmt.Fprintf(os.Stderr, "error: create temp manifest: %v\n", err)
399			return 1
400		}
401		tmpPath := tmpFile.Name()
402		defer os.Remove(tmpPath)
403		if _, err := tmpFile.Write(manifestData); err != nil {
404			if closeErr := tmpFile.Close(); closeErr != nil {
405				fmt.Fprintf(os.Stderr, "error: close temp manifest after write failure: %v\n", closeErr)
406			}
407			fmt.Fprintf(os.Stderr, "error: write temp manifest: %v\n", err)
408			return 1
409		}
410		if err := tmpFile.Close(); err != nil {
411			fmt.Fprintf(os.Stderr, "error: close temp manifest: %v\n", err)
412			return 1
413		}
414	
415		if _, err := modelcatalog.Load(modelcatalog.LoadOptions{
416			ManifestPath:    tmpPath,
417			RequireExternal: true,
418		}); err != nil {
419			fmt.Fprintf(os.Stderr, "error: validate downloaded manifest: %v\n", err)
420			return 1
421		}
422	
423		if err := os.Rename(tmpPath, manifestPath); err != nil {
424			fmt.Fprintf(os.Stderr, "error: install manifest: %v\n", err)
425			return 1
426		}
427	
428		fmt.Printf("installed catalog %s to %s\n", index.CatalogVersion, manifestPath)
429		return 0
430	}
