499	func fetchCatalogIndex(baseURL, channel, version string) (catalogdist.Index, string, error) {
500		baseURL = strings.TrimRight(strings.TrimSpace(baseURL), "/")
501		if baseURL == "" {
502			return catalogdist.Index{}, "", fmt.Errorf("catalog base URL is required")
503		}
504		channel = strings.TrimSpace(channel)
505		version = strings.TrimSpace(version)
506	
507		indexPath := "stable/index.json"
508		if version != "" {
509			indexPath = path.Join("versions", version, "index.json")
510		} else if channel != "" {
511			indexPath = path.Join(channel, "index.json")
512		}
513	
514		indexURL := baseURL + "/" + indexPath
515		data, err := fetchURL(indexURL)
516		if err != nil {
517			return catalogdist.Index{}, "", err
518		}
519		var index catalogdist.Index
520		if err := json.Unmarshal(data, &index); err != nil {
521			return catalogdist.Index{}, "", fmt.Errorf("decode catalog index %s: %w", indexURL, err)
522		}
523		return index, indexURL, nil
524	}
