526	func fetchURL(rawURL string) ([]byte, error) {
527		client := &http.Client{Timeout: 10 * time.Second}
528		resp, err := client.Get(rawURL) // #nosec G107 -- URL is explicit operator input for catalog sync commands.
529		if err != nil {
530			return nil, fmt.Errorf("fetch %s: %w", rawURL, err)
531		}
532		defer resp.Body.Close()
533		if resp.StatusCode != http.StatusOK {
534			body, _ := io.ReadAll(io.LimitReader(resp.Body, 512))
535			return nil, fmt.Errorf("fetch %s: status %d: %s", rawURL, resp.StatusCode, strings.TrimSpace(string(body)))
536		}
537		data, err := io.ReadAll(resp.Body)
538		if err != nil {
539			return nil, fmt.Errorf("read %s: %w", rawURL, err)
540		}
541		return data, nil
542	}
